    ctx.shadowOffsetY = Math.min(W, H) * 0.012;
    ctx.fillStyle = '#fff8f0';
    ctx.fillRect(-border, -border, pw + border * 2, ph + border * 2);
    ctx.shadowColor = 'transparent';
    ctx.shadowBlur = 0;
    ctx.shadowOffsetY = 0;
